import { defineCollection, z } from 'astro:content';
import { glob } from 'astro/loaders';

// English pages: generated by scripts/import-content.mjs — edit the scrape or the migration rules, not these files.
// Translated pages (pages-<lang>): hand-maintained translations of the English files, same paths and same `url`
// (the English URL is the shared key; the /<lang>/ prefix is added at render time). See TRANSLATION-GUIDE-<LANG>.md.
// Routes come from `url`, never from the file path.
const pageSchema = z.object({
  url: z.string().regex(/^\/(?:[^?#]*\/)?$/, 'url must start and end with "/"'),
  slug: z.string(),
  /** H1 rendered by the layout; null when the body carries its own H1. */
  title: z.string().nullable(),
  titleGenerated: z.boolean().optional(),
  navLabel: z.string().nullable(),
  parent: z.string().nullable(),
  order: z.number().nullable(),
  orphan: z.boolean(),
  pendingReview: z.boolean().optional(),
  wpId: z.number().nullable(),
  postType: z.enum(['page', 'post']),
  lastmod: z.coerce.date().nullable(),
  /** WordPress publish date (Yoast JSON-LD); null when the cached page has none. */
  published: z.coerce.date().nullable().optional(),
  seo: z.object({
    title: z.string().nullable(),
    description: z.string().nullable(),
    ogImage: z.string().nullable(),
    robots: z.string().nullable(),
  }),
  /** Page banner pulled out of the top of the body by the import (rendered by the Hero component). */
  hero: z
    .object({
      video: z.string().nullable(),
      poster: z.string().nullable(),
      image: z.string().nullable(),
      tagline: z.string().nullable(),
    })
    .optional(),
  /** Product spec bullets pulled out of the body by the import (key facts + material cards). */
  specs: z.array(z.object({ label: z.string(), value: z.string() })).optional(),
  specsIntro: z.string().optional(),
  /** Hub bodies are card dumps on the old site; the import trims them (see migration-rules HUB_BODY). */
  bodyTrimmed: z.enum(['intro', 'none']).optional(),
  media: z.array(
    z.object({
      order: z.number(),
      type: z.enum(['image', 'video', 'background', 'embed']),
      src: z.string(),
      alt: z.string().nullable().optional(),
      section: z.number().nullable().optional(),
      poster: z.string().nullable().optional(),
    }),
  ),
  /** Answer-first summary (40–60 words) shown above guide articles; also the card excerpt and llms.txt line. */
  summary: z.string().optional(),
  faq: z.array(z.object({ q: z.string(), a: z.string() })).optional(),
  legacyUrls: z.array(z.string()).optional(),
});

const pagesIn = (base: string) =>
  defineCollection({
    loader: glob({ pattern: '**/*.md', base, generateId: ({ data }) => String(data.url) }),
    schema: pageSchema,
  });

export const collections = {
  pages: pagesIn('./src/content/pages'),
  pagesTr: pagesIn('./src/content/pages-tr'),
  pagesDe: pagesIn('./src/content/pages-de'),
  pagesFr: pagesIn('./src/content/pages-fr'),
  pagesAr: pagesIn('./src/content/pages-ar'),
  pagesRu: pagesIn('./src/content/pages-ru'),
};
